
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_gam_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_gam", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.191324656252326e-03, -1.810731940000073e-03, -1.435098407817366e-03, -1.244779227256401e-03, -1.669985418939722e-03, -3.620925419134987e-03, -8.784632932995827e-03, -1.969427626658210e-02, -3.868258929256008e-02, -6.186562568904646e-02, -5.889517073680735e-02, -7.262374191838022e-03, -9.537610591603073e-04, -3.742987241939750e-04, -2.175257573068114e-02, -8.886676122144563e-03, 5.134587675978967e-02, 1.828683725347244e-02, 1.953728404117735e-04, -2.938248589962494e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


